const body = $input.first().json.body || $input.first().json;

const item_id     = (body.item_id || '').trim().toUpperCase();
const canal       = (body.canal || 'web').toLowerCase();
const conversa_id = body.conversa_id || null;
const telefone    = (body.telefone || '').replace(/\D/g, '');
const nome        = body.nome || 'Cliente';
const email       = body.email || '';

if (!item_id) throw new Error('item_id é obrigatório');

const VALIDOS = [
  'SYNAPSE-ASSINATURA-ESS-BASE',
  'SYNAPSE-ASSINATURA-ESS-CAPT',
  'SYNAPSE-ASSINATURA-ESS-W2',
  'SYNAPSE-ASSINATURA-ESS-W4',
  'SYNAPSE-ASSINATURA-NEG-BASE',
  'SYNAPSE-ASSINATURA-NEG-CAPT',
  'SYNAPSE-ASSINATURA-NEG-W2',
  'SYNAPSE-ASSINATURA-NEG-W4',
  'SYNAPSE-ASSINATURA-PRO-BASE',
  'SYNAPSE-ASSINATURA-PRO-CAPT',
  'SYNAPSE-ASSINATURA-PRO-W2',
  'SYNAPSE-ASSINATURA-PRO-W4',
  'SYNAPSE-ASSINATURA-ENT-BASE',
  'SYNAPSE-ASSINATURA-ENT-CAPT',
  'SYNAPSE-ASSINATURA-ENT-W2',
  'SYNAPSE-ASSINATURA-ENT-W4'
];

if (!VALIDOS.includes(item_id)) {
  throw new Error(`Variante inválida: ${item_id}`);
}

return [{ json: { item_id, canal, conversa_id, telefone, nome, email } }];

const result = $input.first().json;
const preco = result?.message?.price_list_rate;
const item_id = $node['Valida e Extrai Payload'].json.item_id;

if (!preco || preco <= 0) {
  throw new Error(`Preço não encontrado para ${item_id}. Verifique a lista de preços Venda Padrão no ERPNext.`);
}

const NOMES = {
  'SYNAPSE-ASSINATURA-ESS-BASE':  'Synapse Essencial',
  'SYNAPSE-ASSINATURA-ESS-CAPT':  'Synapse Essencial + Captação',
  'SYNAPSE-ASSINATURA-ESS-W2':    'Synapse Essencial + Logística',
  'SYNAPSE-ASSINATURA-ESS-W4':    'Synapse Essencial + Pós-venda',
  'SYNAPSE-ASSINATURA-NEG-BASE':  'Synapse Negócio',
  'SYNAPSE-ASSINATURA-NEG-CAPT':  'Synapse Negócio + Captação',
  'SYNAPSE-ASSINATURA-NEG-W2':    'Synapse Negócio + Logística',
  'SYNAPSE-ASSINATURA-NEG-W4':    'Synapse Negócio + Pós-venda',
  'SYNAPSE-ASSINATURA-PRO-BASE':  'Synapse Profissional',
  'SYNAPSE-ASSINATURA-PRO-CAPT':  'Synapse Profissional + Captação',
  'SYNAPSE-ASSINATURA-PRO-W2':    'Synapse Profissional + Logística',
  'SYNAPSE-ASSINATURA-PRO-W4':    'Synapse Profissional + Pós-venda',
  'SYNAPSE-ASSINATURA-ENT-BASE':  'Synapse Enterprise',
  'SYNAPSE-ASSINATURA-ENT-CAPT':  'Synapse Enterprise + Captação',
  'SYNAPSE-ASSINATURA-ENT-W2':    'Synapse Enterprise + Logística',
  'SYNAPSE-ASSINATURA-ENT-W4':    'Synapse Enterprise + Pós-venda'
};

return [{
  json: {
    item_id,
    nome_plano: NOMES[item_id] || item_id,
    preco: parseFloat(preco),
    canal: $node['Valida e Extrai Payload'].json.canal,
    conversa_id: $node['Valida e Extrai Payload'].json.conversa_id,
    telefone: $node['Valida e Extrai Payload'].json.telefone,
    nome: $node['Valida e Extrai Payload'].json.nome,
    email: $node['Valida e Extrai Payload'].json.email
  }
}];

const pix = $input.first().json;
const meta = $node['Processa Preço e Metadados'].json;

if (!pix.id || !pix.pix?.qr_code) {
  throw new Error('InfinitePay não retornou QR Code. Verifique token e configuração da conta.');
}

return [{
  json: {
    charge_id:   pix.id,
    qr_code:     pix.pix.qr_code,
    qr_code_url: pix.pix.qr_code_url || null,
    valor:       meta.preco,
    nome_plano:  meta.nome_plano,
    item_id:     meta.item_id,
    canal:       meta.canal,
    conversa_id: meta.conversa_id,
    telefone:    meta.telefone,
    nome:        meta.nome
  }
}];
